import{_ as s,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"04 | K8s的沟通语言YAML文件","description":"","frontmatter":{},"headers":[{"level":2,"title":"命令式与声明式","slug":"命令式与声明式","link":"#命令式与声明式","children":[]},{"level":2,"title":"YAML 文件的优势","slug":"yaml-文件的优势","link":"#yaml-文件的优势","children":[]},{"level":2,"title":"YAML 文件语法","slug":"yaml-文件语法","link":"#yaml-文件语法","children":[{"level":3,"title":"键值对","slug":"键值对","link":"#键值对","children":[]},{"level":3,"title":"基础数据类型","slug":"基础数据类型","link":"#基础数据类型","children":[]},{"level":3,"title":"缩进","slug":"缩进","link":"#缩进","children":[]},{"level":3,"title":"列表","slug":"列表","link":"#列表","children":[]},{"level":3,"title":"嵌套结构","slug":"嵌套结构","link":"#嵌套结构","children":[]},{"level":3,"title":"注释与分割符","slug":"注释与分割符","link":"#注释与分割符","children":[]}]},{"level":2,"title":"K8s 中 YAML 文件组成","slug":"k8s-中-yaml-文件组成","link":"#k8s-中-yaml-文件组成","children":[]},{"level":2,"title":"如何编写 YAML 文件","slug":"如何编写-yaml-文件","link":"#如何编写-yaml-文件","children":[{"level":3,"title":"查看资源对象的 apiVersion 和 kind","slug":"查看资源对象的-apiversion-和-kind","link":"#查看资源对象的-apiversion-和-kind","children":[]},{"level":3,"title":"查看资源对象属性含义","slug":"查看资源对象属性含义","link":"#查看资源对象属性含义","children":[]},{"level":3,"title":"通过官方模板编写文件","slug":"通过官方模板编写文件","link":"#通过官方模板编写文件","children":[]},{"level":3,"title":"通过命令自动生成 YAML 文件模板","slug":"通过命令自动生成-yaml-文件模板","link":"#通过命令自动生成-yaml-文件模板","children":[]},{"level":3,"title":"编写 YAML 文件的注意事项","slug":"编写-yaml-文件的注意事项","link":"#编写-yaml-文件的注意事项","children":[]}]},{"level":2,"title":"如何使用 YAML 文件","slug":"如何使用-yaml-文件","link":"#如何使用-yaml-文件","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"零基础拿下云原生CKA认证/04｜K8s的沟通语言YAML文件.md","filePath":"零基础拿下云原生CKA认证/04｜K8s的沟通语言YAML文件.md","lastUpdated":1795561650000}'),l={name:"零基础拿下云原生CKA认证/04｜K8s的沟通语言YAML文件.md"};function i(t,a,c,o,r,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="_04-k8s的沟通语言yaml文件" tabindex="-1">04 | K8s的沟通语言YAML文件 <a class="header-anchor" href="#_04-k8s的沟通语言yaml文件" aria-label="Permalink to &quot;04 | K8s的沟通语言YAML文件&quot;">​</a></h1><p>你好，我是雪飞。</p><p>上一课我介绍了 K8s 的管理节点和工作节点上的组件，以及 K8s 丰富的资源对象，这些资源对象就像 K8s 给我们提供的工具包，满足了我们部署应用和管理集群的各种要求。有两种方式与这些资源对象打交道：一种是使用 kubectl 命令，另一种是使用 YAML 文件。它们分别对应着命令式与声明式这两种操作模式。</p><h2 id="命令式与声明式" tabindex="-1">命令式与声明式 <a class="header-anchor" href="#命令式与声明式" aria-label="Permalink to &quot;命令式与声明式&quot;">​</a></h2><p>命令式操作就像是直接下达指令，比如告诉 K8s 创建或删除某个资源对象。这种方式很直接，但如果是多人同时操作或者频繁修改，就可能引发混乱，因为它不会记录所有的操作过程。</p><p>声明式操作则是向 K8s 说明对于某个资源对象你所期望达到的状态，使用 “kubectl apply” 命令让 K8s 读取文件并且自动将资源对象的当前状态变更为你所期望的状态。这种方式的好处在于，你可以随时查看声明文件，清晰地知道资源对象的期望状态，并可以通过修改文件来实现对资源对象的管理。</p><p>简单来说，命令式操作适合快速执行简单任务，而声明式操作则适合需要精细管理的复杂场景，特别是在团队协作和自动化部署中非常有用。K8s 鼓励使用声明式操作，因为这种方式更符合 K8s 自动化和自我修复的设计哲学。</p><h2 id="yaml-文件的优势" tabindex="-1">YAML 文件的优势 <a class="header-anchor" href="#yaml-文件的优势" aria-label="Permalink to &quot;YAML 文件的优势&quot;">​</a></h2><p>YAML（YAML Ain’t Markup Language）文件就是 K8s 中最常用的声明式文件类型，CKA 考试中也会让你实际编写或者修改 YAML 文件，从而完成对 K8s 资源对象的操作。使用 YAML文件有这样几个优势。</p><p>首先，YAML 文件能够处理复杂的数据结构，比如嵌套的列表和字典。它允许在同一个文件中定义多个相互关联的资源对象，这使得 YAML 文件非常适合描述 K8s 资源对象的复杂关系。</p><p>其次，YAML 文件是纯文本格式，它的结构清晰，易于理解和编辑，这可以轻松地存储在如Git 这种版本控制系统中，便于跟踪和管理文件的变更历史，这对于生产环境的应用部署维护至关重要。</p><p>最后，YAML 文件的可重用性和可共享性，使得在不同环境（如开发、测试和生产）间部署资源对象变得简单。你可以为每个环境定义不同的 YAML 文件，或者使用相同的文件但是覆盖特定的参数。</p><p>所以，使用 YAML 文件进行 K8s 的容器化应用部署是一种最佳实践，它提升了集群管理和应用部署的效率、可靠性及可维护性。接下来，我们看一下 YAML 文件的结构组成。</p><h2 id="yaml-文件语法" tabindex="-1">YAML 文件语法 <a class="header-anchor" href="#yaml-文件语法" aria-label="Permalink to &quot;YAML 文件语法&quot;">​</a></h2><p>YAML 文件的结构是基于键值对的层级系统，通过缩进来表示数据之间的层次关系。下面我来简单介绍 YAML 文件的一些基本元素和规则。</p><h3 id="键值对" tabindex="-1">键值对 <a class="header-anchor" href="#键值对" aria-label="Permalink to &quot;键值对&quot;">​</a></h3><p>YAML 文件由一系列的键值对 “key: value” 组成，其中键和值之间使用冒号（：）和空格进行分隔。键 key 是字符串类型，值 value 可以是基础数据类型，也可以是列表或字典这种复合类型。</p><h3 id="基础数据类型" tabindex="-1">基础数据类型 <a class="header-anchor" href="#基础数据类型" aria-label="Permalink to &quot;基础数据类型&quot;">​</a></h3><p>YAML 文件支持多种数据类型，包括字符串、整数、浮点数、布尔值（True 和 False）、空值（Null）等。字符串可以不使用引号，但如果包含特殊字符，则需要使用单引号或双引号，多行字符串可以使用 “|” 和 “&gt;” 符号连接。</p><h3 id="缩进" tabindex="-1">缩进 <a class="header-anchor" href="#缩进" aria-label="Permalink to &quot;缩进&quot;">​</a></h3><p>YAML 文件中使用缩进来表示层级关系。通常，每个层级的缩进为两个空格。缩进格式非常重要，也很容易出错，你在写 YAML 文件时一定要多注意。例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>parent_key:</span></span>
<span class="line"><span> child_key: child_value</span></span></code></pre></div><h3 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h3><p>YAML 文件中的列表使用短横线（-）表示，每个列表项都在新的一行。列表项可以是简单的值，也可以是嵌套的结构。例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>list_key:</span></span>
<span class="line"><span>- item1</span></span>
<span class="line"><span>- item2</span></span>
<span class="line"><span>- sub_list:</span></span>
<span class="line"><span> - sub_item1</span></span>
<span class="line"><span> - sub_item2</span></span></code></pre></div><h3 id="嵌套结构" tabindex="-1">嵌套结构 <a class="header-anchor" href="#嵌套结构" aria-label="Permalink to &quot;嵌套结构&quot;">​</a></h3><p>YAML 文件支持多层嵌套结构，可以通过增加缩进来表示。例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nested_key:</span></span>
<span class="line"><span> first_level:</span></span>
<span class="line"><span>   second_level: second_level_value</span></span>
<span class="line"><span> another_first_level: another_second_level_value</span></span></code></pre></div><h3 id="注释与分割符" tabindex="-1">注释与分割符 <a class="header-anchor" href="#注释与分割符" aria-label="Permalink to &quot;注释与分割符&quot;">​</a></h3><p>YAML 文件通常使用 “#” 号开头作为单行注释，使用 “—” 三个短横线作为分割多个文档。</p><p>这些 YAML 文件的语法是不是很简单呢？基本上你在写 K8s 的 YAML 文件时，记住这些写法就够了。</p><h2 id="k8s-中-yaml-文件组成" tabindex="-1">K8s 中 YAML 文件组成 <a class="header-anchor" href="#k8s-中-yaml-文件组成" aria-label="Permalink to &quot;K8s 中 YAML 文件组成&quot;">​</a></h2><p>在 K8s 中，通过 YAML 文件来描述一个资源对象需要有固定的格式。其中包含了通用的常规属性（也称作字段），也包含不同类型资源对象所具有的特殊含义的属性。简单来说，K8s 的YAML 文件中所涉及到 Key 都是事先定义好的，有的是通用的属性，也有定义不同类型资源对象所需要的属性。所以你需要熟悉这些属性，才能写好 K8s 的 YAML 文件。</p><p>一个典型的 K8s 资源对象的 YAML 文件包含以下几个通用属性：</p><ul><li><p>apiVersion：定义要创建的资源对象对应使用的 API 的版本。这决定了 K8s 使用哪个 API模式来解析文件中的属性。</p></li><li><p>kind：定义要创建的资源对象的类型，如 Pod、Service、Deployment 等。</p></li><li><p>metadata：提供关于要创建的资源对象的基本信息，如名称、命名空间、标签、注解等。</p></li><li><p>spec：描述要创建的资源对象的期望状态及相关特殊属性，如容器的镜像、端口配置、持久化卷声明等。</p></li></ul><p>下面是一个简单的 Pod 资源对象的 YAML 文件（nginx-pod.yaml）示例，YAML 文件后缀名可以使用 “.yaml ” 或 “.yml”。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># nginx-pod.yaml</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: Pod</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: nginx-pod</span></span>
<span class="line"><span> labels:</span></span>
<span class="line"><span>   app: nginx</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> containers:</span></span>
<span class="line"><span>   - name: nginx-container</span></span>
<span class="line"><span>     image: nginx:latest # latest表示使用镜像的最新版本</span></span>
<span class="line"><span>     ports:</span></span>
<span class="line"><span>       - containerPort: 80</span></span></code></pre></div><p>在这个例子中，apiVersion 指定了 Pod 使用的 API 是 v1 版本；kind 指定了要创建的资源对象是一个 Pod；metadata 里定义了 Pod 的名称是叫 nginx-pod，并且 Pod 有一个标签是 “app:nginx”；Spec 的部分描述了 Pod 的规格，即该 Pod 中要运行的容器名称是 nginx-container，容器镜像是 “nginx:latest”，容器暴露端口是 80 端口。</p><p>除了 Pod 之外，K8s 的其他资源对象（如 Deployment、Service、ConfigMap 等）也都是用类似的 YAML 文件格式进行定义和配置。看懂、能够手写并且能够修改 YAML 文件，这是CKA 考试中的必备技能，所以你一定要上手去编写 YAML 文件，多敲几遍，多运行几次，基本上就能掌握了。</p><h2 id="如何编写-yaml-文件" tabindex="-1">如何编写 YAML 文件 <a class="header-anchor" href="#如何编写-yaml-文件" aria-label="Permalink to &quot;如何编写 YAML 文件&quot;">​</a></h2><p>下面你就来自己动手编写一个 YAML 文件吧。在编写 K8s 的 YAML 文件的过程中，有几个小技巧能帮你写出正确美观的 YAML 文件。我给你介绍一下。</p><h3 id="查看资源对象的-apiversion-和-kind" tabindex="-1">查看资源对象的 apiVersion 和 kind <a class="header-anchor" href="#查看资源对象的-apiversion-和-kind" aria-label="Permalink to &quot;查看资源对象的 apiVersion 和 kind&quot;">​</a></h3><p>确定好要创建的资源对象类型之后，就需要查看它的 apiVersion 和 kind 属性，毕竟 YAML 文件的前两行就是这两个属性。你可以在终端窗口中输入 “kubectl api-resources” 命令，它能列出所有的 K8s 资源对象对应的缩写、API 版本、类型名称以及是否支持命名空间。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl api-resources</span></span>
<span class="line"><span>NAME                    SHORTNAMES   APIVERSION  NAMESPACED   KIND</span></span>
<span class="line"><span>bindings                             v1          true         Binding</span></span>
<span class="line"><span>componentstatuses       cs           v1          false        ComponentStatus</span></span>
<span class="line"><span>configmaps              cm           v1          true         ConfigMap</span></span>
<span class="line"><span>endpoints               ep           v1          true         Endpoints</span></span>
<span class="line"><span>events                  ev           v1          true         Event</span></span>
<span class="line"><span>limitranges             limits       v1          true         LimitRange</span></span>
<span class="line"><span>namespaces              ns           v1          false        Namespace</span></span>
<span class="line"><span>nodes                   no           v1          false        Node</span></span>
<span class="line"><span>persistentvolumeclaims  pvc          v1          true         PersistentVolumeCla</span></span>
<span class="line"><span>persistentvolumes       pv           v1          false        PersistentVolume</span></span>
<span class="line"><span>pods                    po           v1          true         Pod</span></span>
<span class="line"><span>deployments             deploy       apps/v1     true         Deployment</span></span>
<span class="line"><span>.......</span></span></code></pre></div><p>我对表头简单解释一下：</p><ul><li><p>SHOTNAMES：资源对象缩写，可以用在 kubectl 命令中，例如，获取 Pod 信息的命令是“kubectl get pod”，但是在上面返回信息中，可以看到 pods 资源对象的缩写是 po，那你就可以用 “kubectl get po” 来代替获取 Pod 信息的命令。</p></li><li><p>APIVERSION：资源对象对应的 API 的版本，也就是 YAML 文件中的 apiVersion 属性，写的时候一定要写完整 ，包含整个路径。</p></li><li><p>NAMESPACE：表示资源对象是否支持命名空间，命名空间 Namespace 是对资源对象的一种逻辑隔离方式，通过将资源对象划分到不同的命名空间中， 从而对它们进行分组管理。</p></li><li><p>KIND：表示资源对象的类型，也就是 YAML 文件中的 kind 属性。</p></li></ul><h3 id="查看资源对象属性含义" tabindex="-1">查看资源对象属性含义 <a class="header-anchor" href="#查看资源对象属性含义" aria-label="Permalink to &quot;查看资源对象属性含义&quot;">​</a></h3><p>在 K8s 中，每个资源对象都会有一些自己的属性，例如：Pod 有 containers、image、ports等属性，Deployment 有 replicas、selector、template 等属性，我们通过在 YAML 文件中使用这些属性来定义期望的资源对象状态。这些属性之间有着固定的嵌套关系，层级很深并且非常庞杂，很难全部记住它们。所以 K8s 也提供了 “kubectl explain” 命令来查看资源对象的属性介绍。通过返回结果，你可以快速了解这些属性以及用法。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl explain pods.spec.containers</span></span>
<span class="line"><span>KIND:       Pod</span></span>
<span class="line"><span>VERSION:    v1</span></span>
<span class="line"><span>FIELD: containers &lt;[]Container&gt;</span></span>
<span class="line"><span>DESCRIPTION:</span></span>
<span class="line"><span>   List of containers belonging to the pod. Containers cannot currently be</span></span>
<span class="line"><span>   added or removed. There must be at least one container in a Pod. Cannot be</span></span>
<span class="line"><span>   updated.</span></span>
<span class="line"><span>   A single application container that you want to run within a pod.</span></span>
<span class="line"><span>......</span></span>
<span class="line"><span> workingDir    &lt;​string&gt;</span></span>
<span class="line"><span>   Container&#39;s working directory. If not specified, the container runtime&#39;s</span></span>
<span class="line"><span>   default will be used, which might be configured in the container image.</span></span>
<span class="line"><span>   Cannot be updated.</span></span></code></pre></div><h3 id="通过官方模板编写文件" tabindex="-1">通过官方模板编写文件 <a class="header-anchor" href="#通过官方模板编写文件" aria-label="Permalink to &quot;通过官方模板编写文件&quot;">​</a></h3><p>怎样能写出好的 YAML 文件，最好的方式就是去查看 K8s 的官方技术文档。官方文档上有大量 YAML 文件模板，熟练掌握去官方文档上查找资料非常重要，因为 CKA 考试的时候虽然不能访问外网，但是是可以查阅官方文档，所以在考试中需要编写 YAML 文件，你就可以从官方文档中复制粘贴过来，然后修改一下，这样能保证考试时的效率和准确度。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/04/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/04/1.png" alt=""></a></p><h3 id="通过命令自动生成-yaml-文件模板" tabindex="-1">通过命令自动生成 YAML 文件模板 <a class="header-anchor" href="#通过命令自动生成-yaml-文件模板" aria-label="Permalink to &quot;通过命令自动生成 YAML 文件模板&quot;">​</a></h3><p>如果你没有现成的 YAML 文件模版，也可以使用 kubectl 命令快速生成模板。只需要在kubectl 创建资源对象的命令后面加上 “–dry-run=client -o yaml” 参数就可以生成一个对应的YAML 文件内容，然后就可以保存到文件中。“–dry-run=client” 表示不是真正创建资源对象，而是模拟执行；“-o yaml” 表示输出为 YAML 文件格式的内容。</p><p>例如：使用 “kubectl create” 命令创建 Deployment 的 YAML 文件模板。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployment</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-nginx-deploy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --image=nginx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run=client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yaml</span></span></code></pre></div><p>在命令最后通过 “&gt;” 符号把模板内容保存到 “my-nginx-deploy.yaml” 文件中。通过 “cat” 命令查看文件内容，就可以看到命令生成的 Deployment 的 YAML 文件内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master cka-example-yaml]# cat my-nginx-deploy.yaml</span></span>
<span class="line"><span>apiVersion: apps/v1</span></span>
<span class="line"><span>kind: Deployment</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> creationTimestamp: null</span></span>
<span class="line"><span> labels:</span></span>
<span class="line"><span>   app: my-nginx-deploy</span></span>
<span class="line"><span> name: my-nginx-deploy</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> replicas: 1</span></span>
<span class="line"><span> selector:</span></span>
<span class="line"><span>   matchLabels:</span></span>
<span class="line"><span>     app: my-nginx-deploy</span></span>
<span class="line"><span> strategy: {}</span></span>
<span class="line"><span> template:</span></span>
<span class="line"><span>   metadata:</span></span>
<span class="line"><span>     creationTimestamp: null</span></span>
<span class="line"><span>     labels:</span></span>
<span class="line"><span>       app: my-nginx-deploy</span></span>
<span class="line"><span>   spec:</span></span>
<span class="line"><span>     containers:</span></span>
<span class="line"><span>     - image: nginx</span></span>
<span class="line"><span>       name: nginx</span></span>
<span class="line"><span>       resources: {}</span></span>
<span class="line"><span>status: {}</span></span></code></pre></div><p>在这个 Deployment 的 YAML 文件中，有些属性字段没有用到（creationTimestamp、strategy、resources、status），可以删除这些属性，然后再按照你的要求修改这个模板文件就可以了。</p><p>所以编写 YAML 文件不用死记硬背，你平时多做积累总结，形成自己的或者团队的 YAML 文件模板库。用的时候只需要复制粘贴再做修改，就可以满足大多数的部署需求了。</p><h3 id="编写-yaml-文件的注意事项" tabindex="-1">编写 YAML 文件的注意事项 <a class="header-anchor" href="#编写-yaml-文件的注意事项" aria-label="Permalink to &quot;编写 YAML 文件的注意事项&quot;">​</a></h3><p>我总结了在编写 YAML 文件过程中的一些注意事项，希望能帮你更快地上手编写 YAML 文件。</p><ul><li><p>多使用注释，可以使用 “#” 对 YAML 文件注释，注释的语句不会执行，可以提高可读性和可维护性。</p></li><li><p>多个相关的资源对象可以写在一个 YAML 文件中同时部署，使用 “—” 做分割，例如Deployment 和 Service 通常是一起使用，就可以写到一个 YAML 文件中，部署的时候同时部署。</p></li><li><p>编写 YAML 文件一定要多注意文件格式，比如层级关系缩进 2 个空格，冒号、逗号后缩进1 个空格，注意这些小细节都能帮你写出正确美观的 YAML 文件。</p></li><li><p>建议你将 YAML 文件纳入版本控制系统，例如将 YAML 文件放到 GitHub 仓库，便于跟踪文件更改和历史记录。</p></li></ul><h2 id="如何使用-yaml-文件" tabindex="-1">如何使用 YAML 文件 <a class="header-anchor" href="#如何使用-yaml-文件" aria-label="Permalink to &quot;如何使用 YAML 文件&quot;">​</a></h2><p>编写完成 YAML 文件，就可以实际运行了，可以使用 “kubectl apply -f” 命令来运行 YAML 文件，从而部署文件中的资源对象。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">​YAML文件</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>使用 “kubectl delete -f” 命令，可以删除 YAML 文件中所部署的全部资源对象。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kubectl </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">​YAML文件名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>在正式应用 YAML 文件之前，可以使用 “kubectl apply -f--dry-run” 命令验证文件格式和内容是否正确，此时 YAML 文件并不会真正执行，如果遇到错误可以去修改文件，确保文件的格式和语法都满足要求。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>现在我们来简单回顾一下今天的内容。</p><p>我介绍了 K8s 中的两种操作方式——命令式和声明式。命令式就像是直接对电脑下命令，非常适合快速搞定一些简单的部署任务；而声明式更像是告诉电脑我们想要达到的最终状态，由它来自动实现我们的期望，这种方式特别适合应对那些复杂的项目，尤其是需要团队协作和自动化部署的场景。</p><p>接着，我们深入了解了 YAML 文件的语法结构，它是一种基于键值对的层级文件，支持多种数据类型以及复杂的数组和字典结构，它通过缩进表示嵌套层级，结构清晰，易于理解和编辑，成为 K8s 的应用程序部署的一种最佳实践。</p><p>在 K8s 中，通过 YAML 文件来描述一个资源对象需要有固定的格式。其中包含了通用的常规属性（也称作字段），也包含不同类型资源对象所具有的特殊含义的属性。常规属性包含apiVersion、kind、metadata 以及 spec。不同资源对象的特殊含义的属性不太一样，需要你不断熟悉和积累。</p><p>然后，我还向你介绍了编写一个 K8s 资源对象的 YAML 文件的几个小技巧：通过 “kubectl api-resources” 命令查看资源对象的 apiVersion 和 kind 属性；通过 “kubectl explain” 命令来查看资源对象的属性介绍；通过官方技术文档中的模板编写 YAML 文件；以及通过 “kubectl” 命令来自动生成 YAML 文件模板。</p><p>最后，我们学习了使用 YAML 文件的两个命令，部署资源对象命令 “kubectl apply -f” 和删除资源对象命令“kubectl delete -f”。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这就是今天的全部内容，最后留一道练习题给你。</p><p>你在 K8s 的官方技术文档中找一个 Deployment 的 YAML 文件，直接拷贝到你的集群中，然后通过该 YAML 文件把它部署到你的集群中，部署完成后通过 “kubectl get deployment” 命令查看一下部署状态。</p><p>欢迎你把结果写到留言区。相信经过动手实践，会让你对知识的理解更加深刻。</p>`,80)])])}const k=s(l,[["render",i]]);export{u as __pageData,k as default};
